BEGIN;
CREATE TEMP TABLE ov_checks(test text, result text);
CREATE TEMP TABLE ov_samples(label text, data jsonb);
CREATE TEMP TABLE ov_before AS SELECT (SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY key)::text) FROM public.feature_flags f) flags,(SELECT md5(jsonb_agg(to_jsonb(u) ORDER BY id)::text) FROM public.user_roles u) roles,(SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY id)::text) FROM public.profiles p) profiles,(SELECT count(*) FROM public.reminder_events) reminders;
DO $verify$
DECLARE r record; v jsonb; row_data jsonb; allowed boolean; site_cost boolean; factory_read boolean; factory_cost boolean; d date:='2026-10-06';
 actor uuid:='99b67080-a6eb-4feb-bd8e-92a287b430aa'; ops uuid:='e7554a18-8a12-4f45-b81d-468426c64f8b'; pid uuid:='e4f51cd6-fb25-475e-980a-5e46070d678f'; rid uuid:=gen_random_uuid(); fid uuid:=gen_random_uuid(); modid uuid; bid uuid; taskid uuid; cid uuid; w1 uuid; w2 uuid; expected numeric; amount numeric;
BEGIN
 FOR r IN SELECT ur.user_id,array_agg(ur.role::text) roles FROM public.user_roles ur JOIN public.profiles p ON p.auth_user_id=ur.user_id WHERE p.is_active GROUP BY ur.user_id LOOP
  allowed:=r.roles && ARRAY['managing_director','finance_director','sales_director','architecture_director','super_admin','head_of_projects','planning_head','finance_manager','quantity_surveyor','costing_engineer','site_installation_mgr','head_operations','production_head'];
  PERFORM set_config('request.jwt.claim.sub',r.user_id::text,true);
  SET LOCAL ROLE authenticated;
  IF public.can_view_site_overview(r.user_id) IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Overview helper mismatch for %',r.roles; END IF;
  IF public.can_view_site_overview(gen_random_uuid()) THEN RAISE EXCEPTION 'Helper permits another user'; END IF;
  IF allowed THEN
   v:=public.get_site_overview(d); site_cost:=public.can_view_running_bill(r.user_id); factory_read:=public.can_read_factory(r.user_id); factory_cost:=public.can_view_factory_cost(r.user_id);
   IF (v->'kpis' ? 'cost') IS DISTINCT FROM (site_cost OR factory_cost) THEN RAISE EXCEPTION 'KPI cost mismatch for %',r.roles; END IF;
   FOR row_data IN SELECT value FROM jsonb_array_elements(v->'sites') LOOP
    IF (row_data ? 'cost') IS DISTINCT FROM site_cost THEN RAISE EXCEPTION 'Site cost mismatch for %',r.roles; END IF;
    IF NOT public.is_tier1_or_super(r.user_id) AND NOT public.user_can_access_project(r.user_id,(row_data->>'project_id')::uuid) THEN RAISE EXCEPTION 'Project scope violation'; END IF;
   END LOOP;
   IF (v->'factory'<>'null'::jsonb) IS DISTINCT FROM factory_read THEN RAISE EXCEPTION 'Factory scope mismatch for %',r.roles; END IF;
   IF factory_read AND (v->'factory' ? 'cost') IS DISTINCT FROM factory_cost THEN RAISE EXCEPTION 'Factory cost mismatch for %',r.roles; END IF;
  ELSE
   BEGIN PERFORM public.get_site_overview(d); RAISE EXCEPTION 'Unexpected overview access for %',r.roles;
   EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  END IF;
  RESET ROLE;
  INSERT INTO ov_checks VALUES(array_to_string(r.roles,'+'),'PASS: helper binding, access, project scope and cost keys');
 END LOOP;
 SET LOCAL ROLE anon;
 BEGIN PERFORM public.get_site_overview(d); RAISE EXCEPTION 'Anonymous RPC access'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.can_view_site_overview(actor); RAISE EXCEPTION 'Anonymous helper access'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 INSERT INTO ov_checks VALUES('Anonymous RPC and helper','PASS: both denied');
 SELECT w.id INTO w1 FROM public.labour_workers w JOIN public.labour_worker_compensation c ON c.worker_id=w.id WHERE coalesce(c.hourly_rate,c.monthly_salary/208,0)>0 ORDER BY w.id LIMIT 1;
 SELECT w.id INTO w2 FROM public.labour_workers w JOIN public.labour_worker_compensation c ON c.worker_id=w.id WHERE w.id<>w1 AND coalesce(c.hourly_rate,c.monthly_salary/208,0)>0 ORDER BY w.id LIMIT 1;
 SELECT id INTO cid FROM public.labour_contractors LIMIT 1;
 SELECT id INTO modid FROM public.modules WHERE project_id=pid AND NOT is_archived LIMIT 1;
 SELECT b.id,b.schedule_task_id INTO bid,taskid FROM public.project_boq_items b JOIN public.project_boq h ON h.id=b.boq_id WHERE h.project_id=pid AND b.schedule_task_id IS NOT NULL ORDER BY h.version_number DESC,b.sno LIMIT 1;
 INSERT INTO public.project_team_members(project_id,profile_id,role,is_active) SELECT pid,id,'overview_fixture',true FROM public.profiles WHERE auth_user_id=ops AND NOT EXISTS(SELECT 1 FROM public.project_team_members WHERE project_id=pid AND profile_id=public.profiles.id AND is_active);
 INSERT INTO public.daily_measurements(id,project_id,measurement_date,location,trade,report_status,submitted_by,submitted_at,created_by,updated_by,notes) VALUES(rid,pid,d,'site','daily_site_report','submitted',actor,d::timestamp AT TIME ZONE 'Asia/Kolkata',actor,actor,'Overview fixture');
 INSERT INTO public.labour_attendance(work_date,worker_id,project_id,hours,hours_confirmed,recorded_by) VALUES(d,w1,pid,8,true,actor),(d,w2,pid,4,true,actor);
 SELECT coalesce(sum(round(a.hours*coalesce(c.hourly_rate,c.monthly_salary/208,0),2)),0) INTO expected FROM public.labour_attendance a LEFT JOIN public.labour_worker_compensation c ON c.worker_id=a.worker_id WHERE a.project_id=pid AND a.work_date=d AND a.hours>0;
 INSERT INTO public.site_report_task_progress(report_id,project_id,task_id,completion_percentage_after,task_status,created_by,updated_by) VALUES(rid,pid,taskid,50,'ongoing',actor,actor);
 INSERT INTO public.site_report_task_workers(report_id,project_id,task_id,worker_id,hours,created_by,updated_by) VALUES(rid,pid,taskid,w1,8,actor,actor);
 INSERT INTO public.site_report_quantities(report_id,project_id,boq_item_id,today_qty,contractor_id,amount_inr,created_by,updated_by) VALUES(rid,pid,bid,2,cid,250,actor,actor);
 INSERT INTO public.site_report_expenses(report_id,project_id,kind,description,amount_inr,created_by,updated_by) VALUES(rid,pid,'consumable','Fixture consumables',200,actor,actor),(rid,pid,'expense','Fixture expense',50,actor,actor);
 INSERT INTO public.factory_daily_reports(id,report_date,status,notes,submitted_by,submitted_at,created_by,updated_by) VALUES(fid,d,'submitted','Factory fixture',actor,d::timestamp AT TIME ZONE 'Asia/Kolkata',actor,actor);
 INSERT INTO public.factory_labour_attendance(work_date,worker_id,hours,hours_confirmed,effective_hourly_rate,amount,created_by,updated_by) VALUES(d,w1,4,true,100,400,actor,actor);
 INSERT INTO public.factory_report_blocks(report_id,module_id,stage,stage_status,progress_pct,created_by,updated_by) VALUES(fid,modid,'Main Frame','ongoing',50,actor,actor);
 INSERT INTO public.factory_report_expenses(report_id,kind,description,amount_inr,created_by,updated_by) VALUES(fid,'consumable','Factory consumables',100,actor,actor),(fid,'expense','Factory expense',25,actor,actor);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true); SET LOCAL ROLE authenticated;
 v:=public.get_site_overview(d);
 SELECT value INTO row_data FROM jsonb_array_elements(v->'sites') WHERE value->>'project_id'=pid::text;
 amount:=(row_data->'cost'->>'attendance')::numeric+(row_data->'cost'->>'subcontract')::numeric+(row_data->'cost'->>'consumables')::numeric+(row_data->'cost'->>'expenses')::numeric;
 IF row_data IS NULL OR amount IS DISTINCT FROM expected+500 THEN RAISE EXCEPTION 'Site reconciliation mismatch'; END IF;
 IF (row_data->'cost'->>'attendance')::numeric<>expected OR (row_data->'cost'->>'subcontract')::numeric<>250 OR (row_data->'cost'->>'consumables')::numeric<>200 OR (row_data->'cost'->>'expenses')::numeric<>50 THEN RAISE EXCEPTION 'Cost breakdown mismatch'; END IF;
 IF (v->'factory'->'cost'->>'attendance')::numeric<>400 OR (v->'factory'->'cost'->>'consumables')::numeric<>100 OR (v->'factory'->'cost'->>'expenses')::numeric<>25 THEN RAISE EXCEPTION 'Factory reconciliation mismatch'; END IF;
 IF (v->'kpis'->>'people_working')::int<>2 OR (v->'kpis'->>'labour_hours')::numeric<>16 THEN RAISE EXCEPTION 'Distinct cross-location people/hours mismatch'; END IF;
 IF (v->'kpis'->>'activities')::int<>2 THEN RAISE EXCEPTION 'Submitted activities mismatch'; END IF;
 IF (v->'factory'->>'expected')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Tuesday factory expectation mismatch'; END IF;
 IF (row_data->>'last_update')::timestamptz IS DISTINCT FROM (SELECT updated_at FROM public.daily_measurements WHERE id=rid) OR (v->'factory'->>'last_update')::timestamptz IS DISTINCT FROM (SELECT updated_at FROM public.factory_daily_reports WHERE id=fid) THEN RAISE EXCEPTION 'Overview must show the latest edit, not an older submission'; END IF;
 RESET ROLE;
 INSERT INTO ov_samples VALUES('Cost present: Test project, 06/10/2026',jsonb_build_object('name',row_data->'name','status',row_data->'status','hours',row_data->'hours','cost',row_data->'cost','total',amount));
 INSERT INTO ov_samples VALUES('Reconciliation',jsonb_build_object('attendance',expected,'subcontract',250,'consumables',200,'expenses',50,'overview_total',amount,'difference',amount-(expected+500),'factory_total',525));
 INSERT INTO ov_checks VALUES('Submitted site/factory reconciliation and distinct people','PASS');
 INSERT INTO ov_checks VALUES('Site and factory last update reflects the latest edit','PASS');
 PERFORM set_config('request.jwt.claim.sub',ops::text,true); SET LOCAL ROLE authenticated;
 v:=public.get_site_overview(d);
 SELECT value INTO row_data FROM jsonb_array_elements(v->'sites') WHERE value->>'project_id'=pid::text;
 IF row_data IS NULL OR row_data ? 'cost' THEN RAISE EXCEPTION 'Operations site cost exposure'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(row_data->'report'->'expenses') e WHERE e ? 'amount') THEN RAISE EXCEPTION 'Operations expense cost exposure'; END IF;
 RESET ROLE;
 INSERT INTO ov_samples VALUES('Cost absent: head_operations site row',jsonb_build_object('name',row_data->'name','status',row_data->'status','hours',row_data->'hours','cost_key_present',row_data ? 'cost'));
 INSERT INTO ov_checks VALUES('Operations site cost and expense amount omitted','PASS');
 PERFORM set_config('request.jwt.claim.sub',actor::text,true); SET LOCAL ROLE authenticated;
 v:=public.get_site_overview(d+1);
 SELECT value INTO row_data FROM jsonb_array_elements(v->'sites') WHERE value->>'project_id'=pid::text;
 IF row_data IS NULL OR row_data->>'status' IS DISTINCT FROM 'Not started' OR v->'factory'->>'status'<>'Not started' THEN RAISE EXCEPTION 'No-report status mismatch'; END IF;
 IF (row_data->'cost'->>'attendance')::numeric<>0 THEN RAISE EXCEPTION 'Unsubmitted costs counted'; END IF;
 v:=public.get_site_overview('2026-10-11');
 IF (v->'factory'->>'expected')::boolean THEN RAISE EXCEPTION 'Sunday must not be expected'; END IF;
 RESET ROLE;
 INSERT INTO ov_checks VALUES('No report Site and Factory, date change, Sunday','PASS');
 IF (SELECT flags FROM ov_before) IS DISTINCT FROM (SELECT md5(jsonb_agg(to_jsonb(f) ORDER BY key)::text) FROM public.feature_flags f) OR (SELECT roles FROM ov_before) IS DISTINCT FROM (SELECT md5(jsonb_agg(to_jsonb(u) ORDER BY id)::text) FROM public.user_roles u) OR (SELECT profiles FROM ov_before) IS DISTINCT FROM (SELECT md5(jsonb_agg(to_jsonb(p) ORDER BY id)::text) FROM public.profiles p) OR (SELECT reminders FROM ov_before)<>(SELECT count(*) FROM public.reminder_events) THEN RAISE EXCEPTION 'Protected data changed'; END IF;
 INSERT INTO ov_checks VALUES('Flags, roles, accounts, reminder_events unchanged','PASS');
END $verify$;
SELECT jsonb_build_object('checks',(SELECT jsonb_agg(to_jsonb(t) ORDER BY test) FROM ov_checks t),'count',(SELECT count(*) FROM ov_checks),'samples',(SELECT jsonb_agg(to_jsonb(s)) FROM ov_samples s)) evidence;
ROLLBACK;
